/**
 * CLI command for depositing new validators
 *
 * Sends beacon deposit contract calls for the validators of a deposit_data-*.json file
 * generated by ethstaker-deposit-cli.
 */
import { Command } from 'commander';

import type { DepositOptions, GlobalCliOptions } from '../model/commander';
import { deposit } from '../service/domain/deposit';
import { validateDepositSupport } from './validation/cli';

const depositCommand = new Command();

depositCommand
  .name('deposit')
  .description('Deposit new validators from a deposit_data-*.json file of ethstaker-deposit-cli')
  .requiredOption(
    `-d, --deposit-data <path>`,
    'Path to the deposit_data-*.json file generated by ethstaker-deposit-cli'
  )
  .action(async (options: DepositOptions, command) => {
    const globalOptions: GlobalCliOptions = command.parent.opts();
    validateDepositSupport(globalOptions);
    await deposit(globalOptions, options.depositData);
  });

export { depositCommand };
